'use strict';
const Network={stale:false,init(){const pill=document.createElement('span');pill.className='network-pill';pill.id='network-status';pill.setAttribute('role','status');pill.setAttribute('aria-live','polite');pill.setAttribute('aria-atomic','true');document.querySelector('.top-actions').append(pill);const warning=document.createElement('section');warning.className='stock-freshness-warning';warning.id='stock-freshness-warning';warning.hidden=true;warning.setAttribute('role','status');warning.innerHTML='<span>连接中断后，页面已显示数据仅供参考，不是实时库存。</span><button id="refresh-live-stock" class="button secondary">重新联网查询库存</button>';document.querySelector('.topbar').after(warning);$('refresh-live-stock').onclick=async e=>{e.target.disabled=true;try{if(window.ProductContext&&!ProductContext.isCopper()){if(ProductContext.dirty){notify(I18n.language==='en'?'Save or cancel unsaved changes before refreshing.':'请先保存或取消未保存的修改，再重新查询。');return;}await API.request('/cobalt/stock/summary');await Router.show();if([...document.querySelectorAll('#page-content .error')].some(n=>n.textContent.trim()&&n.getClientRects().length)){notify(I18n.language==='en'?'Live data could not be refreshed.':'未联网查询到实时库存');return;}this.stale=false;update();return;}if(location.pathname==='/stock-map'){await StockMap.open();this.stale=false;update();return;}await render();await Dashboard.refresh();if(serviceReady&&Dashboard.snapshot){this.stale=false;update();}else notify('未联网查询到实时库存');}catch(e){notify(e.message);}finally{e.target.disabled=false;}};const panel=document.createElement('section');panel.className='operation-panel';panel.hidden=true;panel.id='operation-panel';panel.setAttribute('aria-live','polite');document.body.append(panel);const update=()=>this.update();window.addEventListener('online',update);window.addEventListener('offline',()=>{this.stale=true;update();});window.addEventListener('stock-stale',()=>{this.stale=true;update();});window.addEventListener('server-response',update);window.addEventListener('operation-state',()=>this.render());window.addEventListener('session-expired',()=>{panel.hidden=true;});API.restoreReceipts();update();},update(){const pill=$('network-status'),warning=$('stock-freshness-warning');if(!pill)return;const state=!navigator.onLine?'offline':this.stale?'disconnected':API.lastServerResponse?'online':'connecting',en=I18n.language==='en',labels={online:['在线','Online'],offline:['离线','Offline'],disconnected:['连接中断','Connection Lost'],connecting:['连接中','Connecting']},hints={online:['已连接服务器。','Connected to the server.'],offline:['设备已离线，请恢复网络后重新查询库存。','Device is offline. Reconnect and refresh stock.'],disconnected:['连接中断，已显示库存可能过时，请重新联网查询。','Connection was interrupted. Displayed stock may be stale; refresh after reconnecting.'],connecting:['正在连接服务器。','Connecting to the server.']};pill.dataset.connectionState=state;pill.dataset.noI18n='';pill.textContent=labels[state][en?1:0];pill.title=hints[state][en?1:0];pill.setAttribute('aria-label',pill.textContent+' · '+pill.title);pill.classList.toggle('error',state==='offline'||state==='disconnected');if(warning)warning.hidden=!this.stale;document.body.classList.toggle('stock-stale',this.stale);this.render();},render(){const panel=$('operation-panel');if(!panel||!window.AppSignedIn)return;const rows=[...API.operations.values()].filter(o=>o.user_id===CurrentUser.id&&['UNKNOWN','SUBMITTING'].includes(o.state));panel.hidden=!rows.length;panel.replaceChildren();for(const o of rows.slice(-3)){const row=document.createElement('div'),text=document.createElement('p');text.textContent=(o.state==='UNKNOWN'?'提交状态未知':'提交中')+' · '+o.method+' '+o.path;row.append(text);if(o.state==='UNKNOWN'){const check=document.createElement('button');check.textContent='重新查询操作结果';check.onclick=async()=>{check.disabled=true;try{const r=await API.check(o.key);notify(r.notice);if(r.committed){if(window.ProductContext&&!ProductContext.isCopper())await Router.show();else await render();}}catch(e){notify(e.message);}finally{check.disabled=false;}};row.append(check);if(o.options){const retry=document.createElement('button');retry.textContent='使用原请求重试';retry.onclick=async()=>{retry.disabled=true;try{await API.retry(o.key);notify('服务器已确认');if(window.ProductContext&&!ProductContext.isCopper())await Router.show();else await render();}catch(e){notify(e.message);}finally{retry.disabled=false;}};row.append(retry);}const hint=document.createElement('small');hint.textContent='请勿另建相同单据。只保留查询凭据，不缓存库存或离线自动提交。';row.append(hint);}panel.append(row);}}};Network.init();
